/* prog28_levenshtein – re‑implementation of the original binary
 *
 * Behaviour:
 *   - If less than two arguments are supplied, prints "USAGE\n".
 *   - If either argument is longer than 64 characters, prints "TOO_LONG\n".
 *   - Otherwise prints the Levenshtein distance between the two strings,
 *     followed by a newline.
 *
 * The implementation follows the same algorithmic steps as the original
 * (initialising the first row/column, then filling the DP table).
 */

#include <stdio.h>
#include <string.h>

#define MAXLEN 64          /* maximum length accepted for each string */
#define DP_SIZE (MAXLEN + 1)

int main(int argc, char *argv[])
{
    /* Argument handling – exactly the same messages as the original. */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *s1 = argv[1];
    const char *s2 = argv[2];

    size_t len1 = strlen(s1);
    size_t len2 = strlen(s2);

    if (len1 > MAXLEN || len2 > MAXLEN) {
        puts("TOO_LONG");
        return 0;
    }

    /* DP table: dp[i][j] = distance between s1[0..i-1] and s2[0..j-1].
     * The original binary used a flat array of 65*65 ints; a 2‑D array
     * is more readable but has identical layout.
     */
    int dp[DP_SIZE][DP_SIZE];

    /* initialise first row and column */
    for (size_t i = 0; i <= len1; ++i)
        dp[i][0] = (int)i;
    for (size_t j = 0; j <= len2; ++j)
        dp[0][j] = (int)j;

    /* fill the rest of the table */
    for (size_t i = 1; i <= len1; ++i) {
        for (size_t j = 1; j <= len2; ++j) {
            int cost = (s1[i - 1] == s2[j - 1]) ? 0 : 1;

            int deletion    = dp[i - 1][j] + 1;
            int insertion   = dp[i][j - 1] + 1;
            int substitution = dp[i - 1][j - 1] + cost;

            int best = deletion;
            if (insertion < best)   best = insertion;
            if (substitution < best) best = substitution;

            dp[i][j] = best;
        }
    }

    /* Output – exactly the same format as the original (printf("%d\n")) */
    printf("%d\n", dp[len1][len2]);
    return 0;
}
